  private <C> void injectPathwayContext(
      AgentSpan span,
      C carrier,
      AgentPropagation.Setter<C> setter,
      LinkedHashMap<String, String> sortedTags,
      long defaultTimestamp,
      long payloadSizeBytes,
      boolean sendCheckpoint) {
