import datadog.trace.bootstrap.config.provider.ConfigConverter;
import java.util.Map;

public class Runner {
  public static void main(String[] args) {
    String prefix = "http.request.headers.";
    String[] inputs = {
      "a,b",
      "a:b c c",
      "dyno:web.1,dynotype:web,buildpackversion:dev",
      "dyno:web.1 dynotype:web buildpackversion:dev",
      "key1 :value1 ,\t key2:  value2",
      "X-Custom-Header",
      "X-Custom-Header:MyCustomTag",
      "a b",
      "a  b",
      "a  :  b",
      "USER-AGENT",
      "user-agent:my_header_tag",
      "UPPER_HEADER:lower_tag",
      "a\t:\tb",
      "a :",
      "a:",
      "x.1:y.2",
      "a b:c d",
      "a: b c",
      "key with space:value",
      "a:b \"c\"",
      "a  b:c",
      "a::b",
      "::",
      "a:b:c,d:e:f",
      "a b c d",
      "",
    };
    for (String in : inputs) {
      Map<String, String> r = ConfigConverter.parseMapWithOptionalMappings(in, "test", prefix, true);
      Map<String, String> rLower = ConfigConverter.parseMapWithOptionalMappings(in, "test", prefix, false);
      System.out.println(
          "IN="
              + quote(in)
              + "\n    lower=true,HDR="
              + r
              + "\n    lower=false,HDR="
              + rLower);
    }
  }

  private static String quote(String s) {
    return "\"" + s.replace("\n", "\\n").replace("\t", "\\t") + "\"";
  }
}

