package com.datadog.appsec.api.security;

import static datadog.remoteconfig.tuf.RemoteConfigRequest.ClientInfo.CAPABILITY_ASM_API_SECURITY_SAMPLE_RATE;

import com.datadog.appsec.config.AppSecFeatures;
import com.datadog.appsec.config.AppSecFeaturesDeserializer;
import datadog.remoteconfig.ConfigurationPoller;
import datadog.remoteconfig.Product;
import datadog.trace.api.Config;
import java.util.concurrent.atomic.AtomicLong;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ApiSecurityRequestSampler {

  private static final Logger log = LoggerFactory.getLogger(ApiSecurityRequestSampler.class);

  public static final String ASM_FEATURES_CONFIG_KEY = "asm_features";

  public static final String ASM_API_SECURITY_CONFIG_KEY = "asm_api_security";

  private volatile int sampling;
  private final AtomicLong cumulativeCounter = new AtomicLong();

  public ApiSecurityRequestSampler(final Config config) {
    sampling = computeSamplingParameter(config.getApiSecurityRequestSampleRate());
  }

  public ApiSecurityRequestSampler(final Config config, final ConfigurationPoller poller) {
    sampling = computeSamplingParameter(config.getApiSecurityRequestSampleRate());
    subscribeForConfigChanges(poller);
  }

  private void subscribeForConfigChanges(final ConfigurationPoller poller) {
    poller.addListener(
        Product.ASM_FEATURES,
        AppSecFeaturesDeserializer.INSTANCE,
        (configKey, features, pollingRateHinter) -> {
          if (features == null || features.apiSecurity == null) {
            return;
          }
          if (configKey.startsWith(ASM_API_SECURITY_CONFIG_KEY)) {
            updateSampling(features.apiSecurity.requestSampleRate);
          }
        });
    poller.addCapabilities(CAPABILITY_ASM_API_SECURITY_SAMPLE_RATE);
  }

  private void updateSampling(final float sampleRate) {
    if (sampleRate < 0) {
      log.debug("Ignoring invalid API security sampling rate: {}", sampleRate);
      return;
    }
    cumulativeCounter.set(0);
    sampling = computeSamplingParameter(sampleRate);
    log.debug("Updated API security sampling rate to {}", sampleRate);
  }

  public boolean sampleRequest() {
    long prevValue = cumulativeCounter.getAndAdd(sampling);
    long newValue = prevValue + sampling;
    if (newValue / 100 == prevValue / 100 + 1) {
      // Sample request
      return true;
    }
    // Skipped by sampling
    return false;
  }

  static int computeSamplingParameter(final float pct) {
    if (pct >= 1) {
      return 100;
    }
    if (pct < 0) {
      // We don't support disabling Api Security by setting it, so we set it to 100%.
      // TODO: We probably want a warning here.
      return 100;
    }
    return (int) (pct * 100);
  }
}
```

