public static TraceState decodeHeader(@Nullable String tracestate) {
    if (tracestate == null
        || tracestate.trim().isEmpty()
        || tracestate.length() > TRACESTATE_MAX_SIZE) {
      return TraceState.getDefault();
    }
    TraceStateBuilder builder = TraceState.builder();
    int count = 0;
    int index = 0;
    while (index < tracestate.length() && count < TRACESTATE_MAX_ENTRIES) {
      int end = tracestate.indexOf(TRACESTATE_ENTRY_DELIMITER, index);
      if (end < 0) {
        end = tracestate.length();
      }
      if (parseEntry(builder, tracestate.substring(index, end))) {
        count++;
      }
      index = end + 1;
    }
    return builder.build();
  }

  private static boolean parseEntry(TraceStateBuilder builder, String entry) {
    int separator = entry.indexOf(TRACESTATE_KEY_VALUE_DELIMITER);
    if (separator <= 0) {
      return false;
    }
    String key = entry.substring(0, separator);
    String value = entry.substring(separator + 1);
    if (!isValidKey(key) || !isValidValue(value)) {
      return false;
    }
    builder.put(key, value);
    return true;
  }

  private static boolean isValidKey(String key) {
    int length = key.length();
    if (length < 1 || length > TRACESTATE_MAX_ENTRY_LENGTH) {
      return false;
    }
    for (int i = 0; i < length; i++) {
      char c = key.charAt(i);
      if (!(c >= '0' && c <= '9') && !(c >= 'a' && c <= 'z') && c != '_' && c != '-') {
        return false;
      }
    }
    return true;
  }

  private static boolean isValidValue(String value) {
    int length = value.length();
    if (length > TRACESTATE_MAX_ENTRY_LENGTH) {
      return false;
    }
    for (int i = 0; i < length; i++) {
      char c = value.charAt(i);
      if (!(c == ' ' || c == '\t' || (c >= 0x21 && c <= 0x2B) || (c >= 0x2D && c <= 0x3A) || (c >= 0x3C && c <= 0x7E))) {
        return false;
      }
    }
    return true;
  }
