public static TraceState decodeHeader(@Nullable String tracestate) {
    if (tracestate == null
        || tracestate.trim().isEmpty()
        || tracestate.length() > TRACESTATE_MAX_SIZE) {
      return TraceState.getDefault();
    }
    TraceStateBuilder builder = TraceState.builder();
    int entryCount = 0;
    int index = tracestate.length();
    // Iterate entries in reverse order to preserve the header order as the builder prepends entries
    while (index > 0 && entryCount < TRACESTATE_MAX_ENTRIES) {
      int start = tracestate.lastIndexOf(TRACESTATE_ENTRY_DELIMITER, index - 1);
      String entry =
          start < 0 ? tracestate.substring(0, index) : tracestate.substring(start + 1, index);
      if (addEntry(builder, entry)) {
        entryCount++;
      }
      index = start;
    }
    return builder.build();
  }
```

