package datadog.trace.instrumentation.opentelemetry14.context.propagation;

import io.opentelemetry.api.trace.TraceState;
import io.opentelemetry.api.trace.TraceStateBuilder;
import javax.annotation.Nullable;

/**
 * Helper to encode/decode the W3C tracestate header as the OpenTelemetry API (1.4) does not expose
 * its internal encoding/decoding utilities. Inspired from the {@code W3CTraceContextEncoding} and
 * {@code ArrayBackedTraceState} internal OpenTelemetry classes only available in API later versions.
 */
public final class TraceStateHelper {
  static final int TRACESTATE_MAX_SIZE = 512;
  static final int TRACESTATE_MAX_ENTRIES = 32;
  private static final int TRACESTATE_ENTRY_MAX_LENGTH = 256;
  private static final char TRACESTATE_ENTRY_DELIMITER = ',';
  private static final char TRACESTATE_KEY_VALUE_DELIMITER = '=';

  private TraceStateHelper() {}

  /**
   * Decodes the given W3C tracestate header into an OpenTelemetry {@link TraceState}.
   *
   * @param tracestate The W3C tracestate header value, or {@code null} when the header is missing.
   * @return The decoded {@link TraceState}, or the default {@link TraceState} when there is no
   *     valid tracestate to decode.
   */
  public static TraceState decodeHeader(@Nullable String tracestate) {
    if (tracestate == null
        || tracestate.trim().isEmpty()
        || tracestate.length() > TRACESTATE_MAX_SIZE) {
      return TraceState.getDefault();
    }
    TraceStateBuilder builder = TraceState.builder();
    int entryCount = 0;
    int index = tracestate.length();
    // Decode the entries in reverse order as the TraceState builder prepends the new entries
    while (index > 0 && entryCount < TRACESTATE_MAX_ENTRIES) {
      int start = tracestate.lastIndexOf(TRACESTATE_ENTRY_DELIMITER, index - 1);
      String entry =
          start < 0 ? tracestate.substring(0, index) : tracestate.substring(start + 1, index);
      if (addEntry(builder, entry)) {
        entryCount++;
      }
      index = start;
    }
    return builder.build();
  }

  /**
   * Encodes the given {@link TraceState} into its W3C tracestate header representation.
   *
   * @param traceState The {@link TraceState} to encode.
   * @return The W3C tracestate header value, or an empty {@link String} when the {@link TraceState}
   *     is empty.
   */
  public static String encodeHeader(TraceState traceState) {
    if (traceState.isEmpty()) {
      return "";
    }
    StringBuilder builder = new StringBuilder(TRACESTATE_MAX_SIZE);
    traceState.forEach(
        (key, value) -> {
          if (builder.length() != 0) {
            builder.append(TRACESTATE_ENTRY_DELIMITER);
          }
          builder.append(key).append(TRACESTATE_KEY_VALUE_DELIMITER).append(value);
        });
    return builder.toString();
  }

  private static boolean addEntry(TraceStateBuilder builder, String entry) {
    int delimiterIndex = entry.indexOf(TRACESTATE_KEY_VALUE_DELIMITER);
    if (delimiterIndex <= 0) {
      // Missing key or key/value delimiter
      return false;
    }
    String key = entry.substring(0, delimiterIndex);
    String value = entry.substring(delimiterIndex + 1);
    if (!isValidKey(key) || !isValidValue(value)) {
      return false;
    }
    builder.put(key, value);
    return true;
  }

  private static boolean isValidKey(String key) {
    int length = key.length();
    if (length == 0 || length > TRACESTATE_ENTRY_MAX_LENGTH) {
      return false;
    }
    for (int index = 0; index < length; index++) {
      char c = key.charAt(index);
      if ((c < '0' || c > '9') && (c < 'a' || c > 'z') && c != '_' && c != '-') {
        return false;
      }
    }
    return true;
  }

  private static boolean isValidValue(String value) {
    int length = value.length();
    if (length == 0 || length > TRACESTATE_ENTRY_MAX_LENGTH) {
      return false;
    }
    for (int index = 0; index < length; index++) {
      char c = value.charAt(index);
      if (c != '\t' && (c < ' ' || c > '~')) {
        return false;
      }
    }
    return true;
  }
}

