package opentelemetry14.context.propagation

import static datadog.trace.instrumentation.opentelemetry14.context.propagation.TraceStateHelper.decodeHeader
import static datadog.trace.instrumentation.opentelemetry14.context.propagation.TraceStateHelper.encodeHeader

import io.opentelemetry.api.trace.TraceState
import spock.lang.Specification

class TraceStateHelperTest extends Specification {

  def "decode tracestate header"() {
    when:
    def traceState = decodeHeader(header)

    then:
    traceState.size() == expectedTraceState.size()
    expectedTraceState.each { key, value -> assert traceState.get(key) == value }

    where:
    header                                               | expectedTraceState
    null                                                 | [:]
    ''                                                   | [:]
    'foo=1'                                              | ['foo': '1']
    'foo=1,bar=2'                                        | ['foo': '1', 'bar': '2']
    'dd=s:0;t.tid:1111111111111111,foo=1'                | ['dd': 's:0;t.tid:1111111111111111', 'foo': '1']
    'foo=1,,bar=2'                                       | ['foo': '1', 'bar': '2']
    'foo'                                                | [:]
    'foo='                                               | [:]
    'FOO=1'                                              | [:]
  }

  def "encode tracestate header"() {
    expect:
    encodeHeader(traceState) == expectedHeader

    where:
    traceState                                                                                                        | expectedHeader
    TraceState.getDefault()                                                                                           | ''
    TraceState.builder().put('foo', '1').build()                                                                      | 'foo=1'
    TraceState.builder().put('key1', 'value1').put('key2', 'value2').put('key3', 'value3').put('key4', 'value4').build() | 'key4=value4,key3=value3,key2=value2,key1=value1'
  }

  def "decode then encode preserves the header"() {
    expect:
    encodeHeader(decodeHeader(header)) == header

    where:
    header << ['foo=1', 'foo=1,bar=2', 'dd=s:0;t.tid:1111111111111111,foo=1']
  }

  def "tracestate header exceeding 32 entries is truncated"() {
    setup:
    def header = (0..39).collect { "key$it=value$it" }.join(',')

    expect:
    decodeHeader(header).size() == 32
  }

  def "oversized tracestate header is rejected"() {
    setup:
    def header = 'foo=' + ('a' * 510)

    expect:
    decodeHeader(header).isEmpty()
  }
}

