package io.opentelemetry.api.trace;

import java.util.function.BiConsumer;
import javax.annotation.Nullable;

public interface TraceState {
  int size();

  boolean isEmpty();

  @Nullable
  String get(String key);

  void forEach(BiConsumer<String, String> consumer);

  TraceStateBuilder toBuilder();

  static TraceState getDefault() {
    return EmptyTraceState.INSTANCE;
  }

  static TraceStateBuilder builder() {
    return new ArrayBackedTraceStateBuilder();
  }
}

package io.opentelemetry.api.trace;

public interface TraceStateBuilder {
  TraceStateBuilder put(String key, String value);

  TraceState build();
}

package io.opentelemetry.api.trace;

import java.util.Arrays;
import java.util.function.BiConsumer;
import javax.annotation.Nullable;

class EmptyTraceState implements TraceState {
  static final TraceState INSTANCE = new EmptyTraceState();

  @Override
  public int size() {
    return 0;
  }

  @Override
  public boolean isEmpty() {
    return true;
  }

  @Nullable
  @Override
  public String get(String key) {
    return null;
  }

  @Override
  public void forEach(BiConsumer<String, String> consumer) {}

  @Override
  public TraceStateBuilder toBuilder() {
    return new ArrayBackedTraceStateBuilder();
  }
}

class ArrayBackedTraceState implements TraceState {
  private final String[] keys;
  private final String[] values;
  private final int size;

  ArrayBackedTraceState(String[] keys, String[] values) {
    this.keys = keys;
    this.values = values;
    this.size = keys.length;
  }

  @Override
  public int size() {
    return this.size;
  }

  @Override
  public boolean isEmpty() {
    return this.size == 0;
  }

  @Nullable
  @Override
  public String get(String key) {
    for (int i = 0; i < this.size; i++) {
      if (this.keys[i].equals(key)) {
        return this.values[i];
      }
    }
    return null;
  }

  @Override
  public void forEach(BiConsumer<String, String> consumer) {
    for (int i = 0; i < this.size; i++) {
      consumer.accept(this.keys[i], this.values[i]);
    }
  }

  @Override
  public TraceStateBuilder toBuilder() {
    TraceStateBuilder builder = new ArrayBackedTraceStateBuilder();
    for (int i = this.size - 1; i >= 0; i--) {
      builder.put(this.keys[i], this.values[i]);
    }
    return builder;
  }
}

class ArrayBackedTraceStateBuilder implements TraceStateBuilder {
  private String[] keys = new String[10];
  private String[] values = new String[10];
  private int size;

  @Override
  public TraceStateBuilder put(String key, String value) {
    if (key == null || key.isEmpty() || value == null) {
      throw new IllegalArgumentException();
    }
    if (this.size == this.keys.length) {
      int newCapacity = this.keys.length + 10;
      this.keys = Arrays.copyOf(this.keys, newCapacity);
      this.values = Arrays.copyOf(this.values, newCapacity);
    }
    // The builder prepends the new entry
    if (this.size > 0) {
      System.arraycopy(this.keys, 0, this.keys, 1, this.size);
      System.arraycopy(this.values, 0, this.values, 1, this.size);
    }
    this.keys[0] = key;
    this.values[0] = value;
    this.size++;
    return this;
  }

  @Override
  public TraceState build() {
    if (this.size == 0) {
      return EmptyTraceState.INSTANCE;
    }
    return new ArrayBackedTraceState(
        Arrays.copyOf(this.keys, this.size), Arrays.copyOf(this.values, this.size));
  }
}

import datadog.trace.instrumentation.opentelemetry14.context.propagation.TraceStateHelper;
import io.opentelemetry.api.trace.TraceState;

public class Runner {
  static int failures = 0;

  static void check(String name, boolean condition, String detail) {
    if (condition) {
      System.out.println("PASS: " + name + (detail != null ? " [" + detail + "]" : ""));
    } else {
      failures++;
      System.out.println("FAIL: " + name + (detail != null ? " [" + detail + "]" : ""));
    }
  }

  public static void main(String[] args) {
    check("null -> default", TraceStateHelper.decodeHeader(null) == TraceState.getDefault(), null);
    check("empty -> default", TraceStateHelper.decodeHeader("") == TraceState.getDefault(), null);
    check("blank -> default", TraceStateHelper.decodeHeader("   ") == TraceState.getDefault(), null);

    TraceState single = TraceStateHelper.decodeHeader("foo=1");
    check("single size", single.size() == 1, "size=" + single.size());
    check("single value", "1".equals(single.get("foo")), String.valueOf(single.get("foo")));

    TraceState multi = TraceStateHelper.decodeHeader("foo=1,bar=2");
    check("multi size", multi.size() == 2, "size=" + multi.size());
    check("multi foo", "1".equals(multi.get("foo")), String.valueOf(multi.get("foo")));
    check("multi bar", "2".equals(multi.get("bar")), String.valueOf(multi.get("bar")));
    check(
        "multi order preserved",
        "foo=1,bar=2".equals(TraceStateHelper.encodeHeader(multi)),
        TraceStateHelper.encodeHeader(multi));

    TraceState dd = TraceStateHelper.decodeHeader("dd=s:0;t.tid:1111111111111111,foo=1");
    check("dd size", dd.size() == 2, "size=" + dd.size());
    check("dd get", "s:0;t.tid:1111111111111111".equals(dd.get("dd")), String.valueOf(dd.get("dd")));
    check("dd foo", "1".equals(dd.get("foo")), String.valueOf(dd.get("foo")));
    check(
        "dd roundtrip",
        "dd=s:0;t.tid:1111111111111111,foo=1".equals(TraceStateHelper.encodeHeader(dd)),
        TraceStateHelper.encodeHeader(dd));

    TraceState skipEmpty = TraceStateHelper.decodeHeader("foo=1,,bar=2");
    check("skip empty size", skipEmpty.size() == 2, "size=" + skipEmpty.size());
    check("skip empty values", "1".equals(skipEmpty.get("foo")) && "2".equals(skipEmpty.get("bar")), null);

    TraceState noDelim = TraceStateHelper.decodeHeader("foo");
    check("no delim -> default", noDelim.isEmpty(), null);
    TraceState emptyValue = TraceStateHelper.decodeHeader("foo=");
    check("empty value -> default", emptyValue.isEmpty(), null);
    TraceState upperKey = TraceStateHelper.decodeHeader("FOO=1");
    check("upper key -> default", upperKey.isEmpty(), null);

    StringBuilder tooMany = new StringBuilder();
    for (int i = 0; i < 40; i++) {
      if (i > 0) {
        tooMany.append(',');
      }
      tooMany.append("key").append(i).append("=value").append(i);
    }
    TraceState truncated = TraceStateHelper.decodeHeader(tooMany.toString());
    check(">32 entries truncated", truncated.size() == 32, "size=" + truncated.size());

    StringBuilder oversized = new StringBuilder("foo=");
    for (int i = 0; i < 510; i++) {
      oversized.append('a');
    }
    check("oversized -> default", TraceStateHelper.decodeHeader(oversized.toString()).isEmpty(), null);

    StringBuilder oversized2 = new StringBuilder();
    for (int i = 0; i < 513; i++) {
      oversized2.append('x');
    }
    check("513 chars -> rejects before parse", TraceStateHelper.decodeHeader(oversized2.toString()).isEmpty(), null);

    TraceState longValue = TraceStateHelper.decodeHeader("foo=" + repeat('a', 257));
    check("256+ value dropped", longValue.isEmpty(), "size=" + longValue.size());

    TraceState emptyTrace = TraceState.builder().build();
    check("encode empty -> ''", "".equals(TraceStateHelper.encodeHeader(emptyTrace)), "[" + TraceStateHelper.encodeHeader(emptyTrace) + "]");

    TraceState built = TraceState.builder().put("key1", "value1").put("key2", "value2").put("key3", "value3").put("key4", "value4").put("key5", "value5").build();
    check(
        "encode builder prepend order",
        "key5=value5,key4=value4,key3=value3,key2=value2,key1=value1".equals(TraceStateHelper.encodeHeader(built)),
        TraceStateHelper.encodeHeader(built));

    System.out.println("\nTotal failures: " + failures);
    if (failures > 0) {
      System.exit(1);
    }
  }

  static String repeat(char c, int n) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
      sb.append(c);
    }
    return sb.toString();
  }
}

